# -*- coding: utf-8 -*-
"""Texts for the new Organ Labs (arm, urinary, pancreas, spine) and journeys (reflex, hormones): parts and steps in
English, Hindi (spoken classroom Hindi, devtools/i18n/HINDI_STYLE.md) and Hinglish. Writes into body/models/content.json."""
import json, sys
APP = '/home/claude/duet-lms-media/body'
def T(en, hi, hg): return {'en': en, 'hi': hi, 'hg': hg}
P, ST, JT = {}, {}, {}
def part(pid, sys_, name, job, process): P[pid] = {'name': name, 'job': job, 'sys': sys_, 'process': process}
def step(k, title, text): ST[k] = {'title': title, 'text': text}

# ================================================================ arm lab
part('musculocutaneous_nerve', 'nervous', T("Musculocutaneous nerve", "मस्कुलोक्यूटेनियस तंत्रिका", "Musculocutaneous nerve"),
  T("Carries the command from the spinal cord to the biceps and brachialis, so they bend the elbow.",
    "मेरुरज्जु से बाइसेप्स और ब्रेकियैलिस तक आदेश ले जाती है, ताकि वे कोहनी मोड़ें।",
    "Spinal cord se biceps aur brachialis tak command le jaati hai, taaki wo elbow modein."),
  T("It starts from the neck part of the spinal cord and comes out through the brachial plexus. It runs between the biceps and the brachialis and gives a branch to each. Below the elbow it becomes a skin nerve that feels the outer side of the forearm.",
    "यह गर्दन वाले मेरुरज्जु से शुरू होती है और ब्रेकियल प्लेक्सस से होकर निकलती है। यह बाइसेप्स और ब्रेकियैलिस के बीच चलती है, और दोनों को एक-एक शाखा देती है। कोहनी के नीचे यह त्वचा की तंत्रिका बन जाती है, जो अग्रबाहु के बाहरी हिस्से को महसूस करती है।",
    "Ye gardan wale spinal cord se shuru hoti hai aur brachial plexus se hokar nikalti hai. Ye biceps aur brachialis ke beech chalti hai, aur dono ko ek-ek branch deti hai. Elbow ke neeche ye skin ki nerve ban jaati hai, jo forearm ke bahar wale hisse ko feel karti hai."))
part('grey_matter', 'nervous', T("Grey matter of the spinal cord", "मेरुरज्जु का धूसर द्रव्य (ग्रे मैटर)", "Spinal cord ka grey matter"),
  T("The butterfly-shaped middle of the spinal cord, full of nerve cells, where messages are passed on and reflexes are made.",
    "मेरुरज्जु का तितली जैसा बीच वाला भाग, जिसमें तंत्रिका कोशिकाएँ भरी हैं। यहीं संदेश आगे दिए जाते हैं और प्रतिवर्ती क्रियाएँ बनती हैं।",
    "Spinal cord ka titli jaisa beech wala hissa, jismein nerve cells bhari hain. Yahin messages aage diye jaate hain aur reflexes bante hain."),
  T("Cut across, the spinal cord shows a grey butterfly inside a white ring. Its back wings receive the sensory nerves. Its front wings hold the motor neurons that send commands to the muscles. Small relay neurons join the two, and that is how a reflex happens without the brain.",
    "मेरुरज्जु को आड़ा काटें, तो सफ़ेद घेरे के अंदर एक धूसर तितली दिखती है। इसके पीछे वाले पंखों में संवेदी तंत्रिकाएँ आती हैं। आगे वाले पंखों में प्रेरक न्यूरॉन (मोटर न्यूरॉन) होते हैं, जो मांसपेशियों को आदेश भेजते हैं। छोटे रिले न्यूरॉन इन दोनों को जोड़ते हैं, और इसी से मस्तिष्क के बिना प्रतिवर्ती क्रिया हो जाती है।",
    "Spinal cord ko aada kaatein, to safed ghere ke andar ek grey titli dikhti hai. Iske peeche wale pankhon mein sensory nerves aati hain. Aage wale pankhon mein motor neurons hote hain, jo muscles ko command bhejte hain. Chhote relay neurons in dono ko jodte hain, aur isi se brain ke bina reflex ho jaata hai."))
part('spinal_ganglion', 'nervous', T("Dorsal root ganglion", "पृष्ठ मूल गुच्छिका (डॉर्सल रूट गैंग्लियन)", "Dorsal root ganglion"),
  T("A small swelling on the back root of each spinal nerve, holding the cell bodies of the sensory neurons.",
    "हर मेरु तंत्रिका की पिछली जड़ पर एक छोटी गाँठ, जिसमें संवेदी न्यूरॉन की कोशिकाएँ होती हैं।",
    "Har spinal nerve ki peeche wali root par ek chhoti gaanth, jismein sensory neurons ki cells hoti hain."),
  T("Every sensory neuron from the skin and muscles has its cell body here, just outside the spinal cord. A long fibre reaches out to the skin, and a short one goes into the spinal cord. So messages about touch, heat and pain pass through it on their way in.",
    "त्वचा और मांसपेशियों से आने वाले हर संवेदी न्यूरॉन की कोशिका यहीं होती है, मेरुरज्जु के ठीक बाहर। इसका एक लंबा रेशा त्वचा तक जाता है, और एक छोटा रेशा मेरुरज्जु के अंदर। इसलिए छूने, गर्मी और दर्द के संदेश अंदर जाते समय इसी से होकर गुज़रते हैं।",
    "Skin aur muscles se aane wale har sensory neuron ki cell yahin hoti hai, spinal cord ke theek bahar. Iska ek lamba fibre skin tak jaata hai, aur ek chhota fibre spinal cord ke andar. Isliye touch, garmi aur dard ke messages andar jaate samay isi se hokar guzarte hain."))
part('elbow_joint', 'skeleton', T("Elbow joint (hinge joint)", "कोहनी का जोड़ (कब्ज़ा जोड़)", "Elbow joint (hinge joint)"),
  T("Where the humerus meets the radius and ulna; it lets the forearm bend and straighten.",
    "जहाँ ह्यूमरस, रेडियस और अल्ना से मिलती है; यह अग्रबाहु को मुड़ने और सीधा होने देता है।",
    "Jahan humerus, radius aur ulna se milti hai; ye forearm ko mudne aur seedha hone deta hai."),
  T("The reel-shaped end of the humerus fits into a hook-shaped notch of the ulna, so the joint moves in one direction only, like a door hinge. Smooth cartilage and a slippery fluid stop the bones rubbing, and ligaments on both sides hold them together. The head of the radius also turns here when we turn the palm up or down.",
    "ह्यूमरस का रील जैसा सिरा अल्ना के हुक जैसे खाँचे में फँसा रहता है, इसलिए यह जोड़ दरवाज़े के कब्ज़े की तरह बस एक ही दिशा में चलता है। चिकनी उपास्थि (कार्टिलेज) और फिसलन वाला द्रव हड्डियों को रगड़ने नहीं देते, और दोनों तरफ़ के स्नायु (लिगामेंट) इन्हें बाँधे रखते हैं। जब हम हथेली को ऊपर-नीचे घुमाते हैं, तो रेडियस का सिरा भी यहीं घूमता है।",
    "Humerus ka reel jaisa sira ulna ke hook jaise khaanche mein phansa rehta hai, isliye ye joint darwaze ke hinge ki tarah bas ek hi direction mein chalta hai. Chikni cartilage aur phisalne wala fluid haddiyon ko ragadne nahi dete, aur dono taraf ke ligaments inhe baandhe rakhte hain. Jab hum palm ko upar-neeche ghumaate hain, to radius ka sira bhi yahin ghoomta hai."))

step('lab-arm-1', T("The arm: bones and muscles", "बाँह: हड्डियाँ और मांसपेशियाँ", "Arm: haddiyaan aur muscles"),
  T("This is a real right arm, with its bones and muscles. Three long bones make it: the humerus in the upper arm, and the radius and ulna in the forearm. The hand has 27 small bones. More than 20 muscles cover them. The big muscle in front of the upper arm is the biceps, and the one at the back is the triceps. Muscles move the bones, and bones meet at joints.",
    "यह असली जैसी दाईं बाँह है, अपनी हड्डियों और मांसपेशियों के साथ। इसमें तीन लंबी हड्डियाँ हैं: ऊपरी बाँह में ह्यूमरस, और अग्रबाहु (फ़ोरआर्म) में रेडियस और अल्ना। हाथ में सत्ताईस छोटी हड्डियाँ होती हैं। इन पर बीस से ज़्यादा मांसपेशियाँ चढ़ी हैं। ऊपरी बाँह के आगे वाली बड़ी मांसपेशी बाइसेप्स है, और पीछे वाली ट्राइसेप्स। मांसपेशियाँ हड्डियों को हिलाती हैं, और हड्डियाँ जोड़ों पर मिलती हैं।",
    "Ye asli jaisi right arm hai, apni haddiyon aur muscles ke saath. Ismein teen lambi haddiyaan hain: upper arm mein humerus, aur forearm mein radius aur ulna. Haath mein sattaais chhoti haddiyaan hoti hain. In par bees se zyaada muscles chadhi hain. Upper arm ke aage wali badi muscle biceps hai, aur peeche wali triceps. Muscles haddiyon ko hilaati hain, aur haddiyaan joints par milti hain."))
step('lab-arm-2', T("The elbow: a hinge joint", "कोहनी: एक कब्ज़ा जोड़", "Elbow: ek hinge joint"),
  T("Watch the elbow. The lower end of the humerus is shaped like a reel, and the ulna hooks around it. So the elbow can bend and straighten in one direction only, like a door on its hinge. This is called a hinge joint. The knee is a hinge joint too. The shoulder is a ball and socket joint, which can turn in every direction.",
    "कोहनी को देखिए। ह्यूमरस का निचला सिरा एक रील जैसा है, और अल्ना उसके चारों ओर हुक की तरह फँसी रहती है। इसलिए कोहनी बस एक ही दिशा में मुड़ और सीधी हो सकती है, बिल्कुल दरवाज़े के कब्ज़े की तरह। इसे कब्ज़ा जोड़ (हिंज जॉइंट) कहते हैं। घुटना भी कब्ज़ा जोड़ है। कंधा कंदुक-खल्लिका जोड़ (बॉल एंड सॉकेट जॉइंट) है, जो हर दिशा में घूम सकता है।",
    "Elbow ko dekhiye. Humerus ka neeche wala sira ek reel jaisa hai, aur ulna uske chaaron taraf hook ki tarah phansi rehti hai. Isliye elbow bas ek hi direction mein mud aur seedhi ho sakti hai, bilkul darwaze ke hinge ki tarah. Ise hinge joint kehte hain. Knee bhi hinge joint hai. Shoulder ball and socket joint hai, jo har direction mein ghoom sakta hai."))
step('lab-arm-3', T("The biceps pulls: the arm bends", "बाइसेप्स खींचती है: बाँह मुड़ती है", "Biceps kheenchti hai: arm mudti hai"),
  T("A muscle can only pull, it can never push. The biceps starts on the shoulder blade, and a strong tendon ties it to the radius, just below the elbow. When it contracts, it gets shorter and fatter, and pulls the forearm up. Feel it yourself: bend your arm and touch your upper arm. The biceps goes hard and bulges!",
    "मांसपेशी सिर्फ़ खींच सकती है, कभी धकेल नहीं सकती। बाइसेप्स कंधे की हड्डी (स्कैपुला) से शुरू होती है, और एक मज़बूत कंडरा (टेंडन) उसे कोहनी के ठीक नीचे रेडियस से बाँधती है। जब यह सिकुड़ती है, तो छोटी और मोटी हो जाती है, और अग्रबाहु को ऊपर खींच लेती है। ख़ुद महसूस कीजिए: अपनी बाँह मोड़िए और ऊपरी बाँह को छूइए। बाइसेप्स सख़्त होकर फूल जाती है!",
    "Muscle sirf kheench sakti hai, kabhi push nahi kar sakti. Biceps shoulder blade se shuru hoti hai, aur ek mazboot tendon use elbow ke theek neeche radius se baandhta hai. Jab ye contract hoti hai, to chhoti aur moti ho jaati hai, aur forearm ko upar kheench leti hai. Khud feel kijiye: apni arm modiye aur upper arm ko chhooiye. Biceps hard hokar phool jaati hai!"))
step('lab-arm-4', T("Muscles work in pairs", "मांसपेशियाँ जोड़ी में काम करती हैं", "Muscles pair mein kaam karti hain"),
  T("If muscles can only pull, how does the arm straighten again? With a second muscle on the other side! The triceps at the back of the upper arm is tied to the tip of the elbow. When the triceps contracts, the biceps relaxes, and the arm straightens. When the biceps contracts, the triceps relaxes. Muscles that pull against each other like this work as a pair.",
    "जब मांसपेशी सिर्फ़ खींच सकती है, तो बाँह फिर से सीधी कैसे होती है? दूसरी तरफ़ की एक और मांसपेशी से! ऊपरी बाँह के पीछे वाली ट्राइसेप्स कोहनी की नोक से बँधी है। जब ट्राइसेप्स सिकुड़ती है, तो बाइसेप्स ढीली हो जाती है, और बाँह सीधी हो जाती है। जब बाइसेप्स सिकुड़ती है, तो ट्राइसेप्स ढीली होती है। ऐसी मांसपेशियाँ, जो एक-दूसरे के उल्टा खींचती हैं, जोड़ी में काम करती हैं।",
    "Jab muscle sirf kheench sakti hai, to arm phir se seedhi kaise hoti hai? Doosri taraf ki ek aur muscle se! Upper arm ke peeche wali triceps elbow ki nok se bandhi hai. Jab triceps contract hoti hai, to biceps relax ho jaati hai, aur arm seedhi ho jaati hai. Jab biceps contract hoti hai, to triceps relax hoti hai. Aisi muscles, jo ek-doosre ke ulta kheenchti hain, pair mein kaam karti hain."))
step('lab-arm-5', T("Helpers and tendons", "मददगार मांसपेशियाँ और कंडराएँ", "Helper muscles aur tendons"),
  T("The biceps is not alone. Under it lies the brachialis, which does most of the bending. The brachioradialis runs from the humerus down to the wrist and helps too. Every muscle is fixed to bones by tendons, the white cords at its ends. Tendons are tough and do not stretch, so the whole pull of the muscle reaches the bone. Bones are tied to other bones by ligaments.",
    "बाइसेप्स अकेली नहीं है। इसके नीचे ब्रेकियैलिस है, जो मोड़ने का ज़्यादातर काम करती है। ब्रेकियोरेडियैलिस ह्यूमरस से कलाई तक जाती है, और यह भी मदद करती है। हर मांसपेशी अपने सिरों पर सफ़ेद डोरियों से हड्डी से जुड़ी है। इन्हें कंडरा (टेंडन) कहते हैं। कंडरा बहुत मज़बूत होती है और खिंचती नहीं, इसलिए मांसपेशी का पूरा खिंचाव हड्डी तक पहुँचता है। एक हड्डी को दूसरी हड्डी से स्नायु (लिगामेंट) बाँधते हैं।",
    "Biceps akeli nahi hai. Iske neeche brachialis hai, jo modne ka zyaadatar kaam karti hai. Brachioradialis humerus se wrist tak jaati hai, aur ye bhi help karti hai. Har muscle apne siron par safed doriyon se haddi se judi hai. Inhe tendons kehte hain. Tendon bahut mazboot hota hai aur khinchta nahi, isliye muscle ka poora pull haddi tak pahunchta hai. Ek haddi ko doosri haddi se ligaments baandhte hain."))
step('lab-arm-6', T("Inside a muscle", "मांसपेशी के अंदर", "Muscle ke andar"),
  T("Look inside the biceps with the magnifier. A muscle is made of thousands of long cells called muscle fibres, packed in bundles. Under a microscope they show light and dark stripes, so this is called striated muscle. When a nerve signal arrives, tiny filaments inside each fibre slide over each other. Every fibre gets shorter, and so the whole muscle pulls. For this, muscles use energy from food and oxygen.",
    "आवर्धक लेंस से बाइसेप्स के अंदर देखिए। मांसपेशी हज़ारों लंबी कोशिकाओं से बनी है, जिन्हें मांसपेशी तंतु (मसल फ़ाइबर) कहते हैं। ये गुच्छों में बँधे रहते हैं। माइक्रोस्कोप में इन पर हल्की और गहरी धारियाँ दिखती हैं, इसलिए इसे रेखित पेशी (स्ट्रायटेड मसल) कहते हैं। जब तंत्रिका से संकेत आता है, तो हर तंतु के अंदर बहुत बारीक धागे, यानी फ़िलामेंट, एक-दूसरे पर खिसकते हैं। हर तंतु छोटा हो जाता है, और पूरी मांसपेशी खींचती है। इसके लिए मांसपेशी भोजन और ऑक्सीजन से ऊर्जा लेती है।",
    "Magnifier se biceps ke andar dekhiye. Muscle hazaaron lambi cells se bani hai, jinhe muscle fibres kehte hain. Ye bundles mein bandhe rehte hain. Microscope mein in par light aur dark stripes dikhti hain, isliye ise striated muscle kehte hain. Jab nerve se signal aata hai, to har fibre ke andar bahut baareek filaments ek-doosre par slide karte hain. Har fibre chhota ho jaata hai, aur poori muscle kheenchti hai. Iske liye muscle khaane aur oxygen se energy leti hai."))
step('lab-arm-7', T("Ouch! The reflex arc", "आउच! प्रतिवर्ती चाप", "Ouch! Reflex arc"),
  T("Now the hand is held over a candle. When the fingers feel the heat, sense cells in the skin send a signal up a sensory nerve to the spinal cord in the neck. There a relay neuron passes it straight to a motor nerve, which tells the biceps to pull. The hand jumps away before you even think! Only after that does the message reach the brain, and you feel the pain. This quick, automatic action is a reflex action, and its path is called the reflex arc.",
    "अब हाथ एक मोमबत्ती के ऊपर है। जैसे ही उँगलियों को गर्मी लगती है, त्वचा की संवेदी कोशिकाएँ एक संकेत भेजती हैं। यह संकेत संवेदी तंत्रिका से होकर गर्दन में मेरुरज्जु (स्पाइनल कॉर्ड) तक पहुँचता है। वहाँ एक रिले न्यूरॉन इसे सीधे प्रेरक तंत्रिका (मोटर नर्व) को दे देता है, और वह बाइसेप्स से कहती है: खींचो! सोचने से पहले ही हाथ झटके से हट जाता है! इसके बाद ही संदेश मस्तिष्क तक पहुँचता है, और हमें दर्द महसूस होता है। ऐसी तेज़, अपने-आप होने वाली क्रिया को प्रतिवर्ती क्रिया (रिफ़्लेक्स एक्शन) कहते हैं, और इसके रास्ते को प्रतिवर्ती चाप (रिफ़्लेक्स आर्क)।",
    "Ab haath ek candle ke upar hai. Jaise hi ungliyon ko garmi lagti hai, skin ke sense cells ek signal bhejte hain. Ye signal sensory nerve se hokar gardan mein spinal cord tak pahunchta hai. Wahan ek relay neuron ise seedhe motor nerve ko de deta hai, aur wo biceps se kehti hai: kheencho! Sochne se pehle hi haath jhatke se hat jaata hai! Iske baad hi message brain tak pahunchta hai, aur humein dard feel hota hai. Aisi tez, apne-aap hone wali action ko reflex action kehte hain, aur iske raaste ko reflex arc."))

# ================================================================ urinary lab
part('aorta', 'circulatory', T("Aorta", "महाधमनी (एओर्टा)", "Aorta"),
  T("The biggest artery of the body. It carries oxygen-rich blood from the heart down through the chest and belly.",
    "शरीर की सबसे बड़ी धमनी। यह हृदय से ऑक्सीजन वाला रक्त छाती और पेट से होते हुए नीचे तक ले जाती है।",
    "Body ki sabse badi artery. Ye heart se oxygen wala blood chest aur pet se hote hue neeche tak le jaati hai."),
  T("The aorta leaves the left ventricle, arches over the heart and runs down in front of the backbone. In the belly it gives branches to the stomach, intestines and both kidneys, and then splits into two arteries for the legs. It is about as thick as a garden pipe.",
    "महाधमनी बाएँ निलय से निकलती है, हृदय के ऊपर मुड़ती है, और रीढ़ की हड्डी के आगे नीचे की ओर जाती है। पेट में यह आमाशय, आँतों और दोनों गुर्दों को शाखाएँ देती है, फिर पैरों के लिए दो धमनियों में बँट जाती है। यह लगभग बगीचे के पाइप जितनी मोटी होती है।",
    "Aorta left ventricle se nikalti hai, heart ke upar mudti hai, aur backbone ke aage neeche ki taraf jaati hai. Pet mein ye stomach, intestines aur dono kidneys ko branches deti hai, phir pairon ke liye do arteries mein bant jaati hai. Ye lagbhag garden pipe jitni moti hoti hai."))
part('iliac_veins', 'circulatory', T("Common iliac veins", "उभयनिष्ठ श्रोणि शिराएँ (इलियक वेन)", "Common iliac veins"),
  T("Two big veins that bring used blood up from the legs and hips and join to form the inferior vena cava.",
    "दो बड़ी शिराएँ, जो पैरों और कूल्हों से इस्तेमाल हुआ रक्त ऊपर लाती हैं और मिलकर निचली महाशिरा बनाती हैं।",
    "Do badi veins, jo pairon aur hips se use hua blood upar laati hain aur milkar inferior vena cava banati hain."),
  T("Each leg's vein joins a vein from the hip region to make a common iliac vein. The two common iliac veins meet in front of the lower backbone and form the inferior vena cava, which carries the blood up to the right side of the heart.",
    "हर पैर की शिरा कूल्हे की एक शिरा से मिलकर उभयनिष्ठ श्रोणि शिरा बनाती है। दोनों ऐसी शिराएँ रीढ़ के निचले हिस्से के आगे मिलकर निचली महाशिरा बनाती हैं, जो रक्त को ऊपर हृदय के दाएँ भाग तक ले जाती है।",
    "Har pair ki vein hip ki ek vein se milkar common iliac vein banati hai. Dono aisi veins backbone ke neeche wale hisse ke aage milkar inferior vena cava banati hain, jo blood ko upar heart ke right side tak le jaati hai."))
step('lab-urinary-1', T("The urinary system", "मूत्र तंत्र", "Urinary system"),
  T("This is the body's cleaning system. Two bean-shaped kidneys sit high at the back of the belly, one on each side of the backbone. Two thin tubes, the ureters, carry urine down to the urinary bladder, a muscular bag. The urethra lets the urine out of the body. The big artery, the aorta, and the big vein, the vena cava, run between the kidneys.",
    "यह शरीर का सफ़ाई तंत्र है। सेम के आकार के दो गुर्दे पेट के पीछे, ऊपर की ओर, रीढ़ की हड्डी के दोनों तरफ़ रहते हैं। दो पतली नलियाँ, यानी मूत्रवाहिनियाँ (यूरेटर), मूत्र को नीचे मूत्राशय तक ले जाती हैं। मूत्राशय मांसपेशियों की एक थैली है। मूत्रमार्ग (यूरेथ्रा) से मूत्र शरीर से बाहर निकलता है। दोनों गुर्दों के बीच से सबसे बड़ी धमनी, महाधमनी, और सबसे बड़ी शिरा, महाशिरा, गुज़रती हैं।",
    "Ye body ka safaai system hai. Sem ke aakaar ki do kidneys pet ke peeche, upar ki taraf, backbone ke dono taraf rehti hain. Do patli naliyaan, yaani ureters, urine ko neeche urinary bladder tak le jaati hain. Bladder muscles ki ek thaili hai. Urethra se urine body se bahar nikalta hai. Dono kidneys ke beech se sabse badi artery, aorta, aur sabse badi vein, vena cava, guzarti hain."))
step('lab-urinary-2', T("Blood comes in to be cleaned", "साफ़ होने के लिए रक्त आता है", "Saaf hone ke liye blood aata hai"),
  T("Each kidney gets blood straight from the aorta through a renal artery. Every minute about a quarter of all the blood pumped by the heart flows through the kidneys. The kidneys take out waste like urea and extra water and salts. The cleaned blood goes back through the renal veins into the vena cava.",
    "हर गुर्दे को महाधमनी से सीधे एक वृक्क धमनी (रीनल आर्टरी) से रक्त मिलता है। हर मिनट, हृदय जितना रक्त पंप करता है, उसका लगभग एक-चौथाई गुर्दों से होकर बहता है। गुर्दे इसमें से यूरिया जैसा कचरा, और ज़्यादा पानी और नमक निकाल लेते हैं। साफ़ रक्त वृक्क शिराओं से होकर वापस महाशिरा में चला जाता है।",
    "Har kidney ko aorta se seedhe ek renal artery se blood milta hai. Har minute, heart jitna blood pump karta hai, uska lagbhag ek-chauthaai kidneys se hokar behta hai. Kidneys ismein se urea jaisa waste, aur extra paani aur namak nikaal leti hain. Saaf blood renal veins se hokar wapas vena cava mein chala jaata hai."))
step('lab-urinary-3', T("Inside a kidney", "गुर्दे के अंदर", "Kidney ke andar"),
  T("Now both kidneys are cut open from the front. The outer layer is the cortex, and inside it are dark cone-shaped pyramids, the medulla. Urine forms in the cortex and medulla and drips from the tips of the pyramids into a funnel, the renal pelvis. From there it flows into the ureter.",
    "अब दोनों गुर्दे सामने से कटे हुए हैं। बाहरी परत कॉर्टेक्स (वल्कुट) है, और इसके अंदर गहरे रंग के शंकु जैसे पिरामिड हैं, जिन्हें मेडुला कहते हैं। मूत्र कॉर्टेक्स और मेडुला में बनता है, और पिरामिडों की नोकों से टपककर एक कीप में जाता है। इस कीप को वृक्क श्रोणि (रीनल पेल्विस) कहते हैं। वहाँ से मूत्र मूत्रवाहिनी में बहता है।",
    "Ab dono kidneys saamne se kati hui hain. Bahar ki layer cortex hai, aur iske andar gehre rang ke cone jaise pyramids hain, jinhe medulla kehte hain. Urine cortex aur medulla mein banta hai, aur pyramids ki nokon se tapakkar ek funnel mein jaata hai. Is funnel ko renal pelvis kehte hain. Wahan se urine ureter mein behta hai."))
step('lab-urinary-4', T("Nephrons: the tiny filters", "नेफ्रॉन: छोटी छलनियाँ", "Nephrons: chhoti chhalniyaan"),
  T("Each kidney has about ten lakh tiny filters called nephrons. In each one, blood is pressed through a ball of capillaries, the glomerulus. Water, salts, sugar and urea pass into a cup around it, Bowman's capsule. As this liquid moves along the long tubule, the useful things, like sugar, most of the water and salts, are taken back into the blood. What is left is urine.",
    "हर गुर्दे में लगभग दस लाख छोटी छलनियाँ होती हैं, जिन्हें नेफ्रॉन कहते हैं। हर नेफ्रॉन में रक्त केशिकाओं के एक गुच्छे, ग्लोमेरुलस, से दबकर छनता है। पानी, नमक, शक्कर और यूरिया इसके चारों ओर बने एक प्याले में चले जाते हैं, जिसे बोमन संपुट (बोमन कैप्सूल) कहते हैं। जब यह द्रव लंबी नलिका में आगे बढ़ता है, तो काम की चीज़ें, जैसे शक्कर, ज़्यादातर पानी और नमक, वापस रक्त में ले ली जाती हैं। जो बचता है, वही मूत्र है।",
    "Har kidney mein lagbhag das laakh chhoti chhalniyaan hoti hain, jinhe nephrons kehte hain. Har nephron mein blood capillaries ke ek guchhe, glomerulus, se dabkar chhanta hai. Paani, namak, sugar aur urea iske chaaron taraf bane ek pyaale mein chale jaate hain, jise Bowman's capsule kehte hain. Jab ye liquid lambi tubule mein aage badhta hai, to kaam ki cheezein, jaise sugar, zyaadatar paani aur namak, wapas blood mein le li jaati hain. Jo bachta hai, wahi urine hai."))
step('lab-urinary-5', T("Down the ureters to the bladder", "मूत्रवाहिनियों से मूत्राशय तक", "Ureters se bladder tak"),
  T("Urine trickles down the two ureters, about 25 centimetres long. Their walls squeeze in waves, so urine moves down even when we lie down. The bladder slowly fills and stretches like a balloon. An adult bladder holds about 400 to 500 millilitres.",
    "मूत्र दोनों मूत्रवाहिनियों से धीरे-धीरे नीचे बहता है। ये लगभग पच्चीस सेंटीमीटर लंबी होती हैं। इनकी दीवारें लहरों में सिकुड़ती हैं, इसलिए लेटे हुए भी मूत्र नीचे जाता रहता है। मूत्राशय धीरे-धीरे भरता है और गुब्बारे की तरह फैलता है। बड़ों का मूत्राशय लगभग चार सौ से पाँच सौ मिलीलीटर मूत्र रख सकता है।",
    "Urine dono ureters se dheere-dheere neeche behta hai. Ye lagbhag pachchees centimetre lambi hoti hain. Inki deewarein waves mein sikudti hain, isliye lete hue bhi urine neeche jaata rehta hai. Bladder dheere-dheere bharta hai aur balloon ki tarah phailta hai. Badon ka bladder lagbhag chaar sau se paanch sau millilitre urine rakh sakta hai."))
step('lab-urinary-6', T("Out through the urethra", "मूत्रमार्ग से बाहर", "Urethra se bahar"),
  T("When the bladder is full, its stretched wall sends a message to the brain. When we go to the toilet, a ring of muscle at the neck of the bladder relaxes, the bladder squeezes, and urine leaves through the urethra. Drink enough water every day and do not hold urine for long. If the kidneys stop working, a machine can clean the blood. This is called dialysis.",
    "जब मूत्राशय भर जाता है, तो उसकी खिंची हुई दीवार मस्तिष्क को संदेश भेजती है। जब हम शौचालय जाते हैं, तो मूत्राशय की गर्दन पर मांसपेशी का एक छल्ला ढीला होता है, मूत्राशय सिकुड़ता है, और मूत्र मूत्रमार्ग से बाहर निकल जाता है। रोज़ पर्याप्त पानी पीजिए, और मूत्र को देर तक मत रोकिए। अगर गुर्दे काम करना बंद कर दें, तो एक मशीन रक्त को साफ़ कर सकती है। इसे डायलिसिस कहते हैं।",
    "Jab bladder bhar jaata hai, to uski khinchi hui deewar brain ko message bhejti hai. Jab hum toilet jaate hain, to bladder ki gardan par muscle ka ek chhalla dheela hota hai, bladder sikudta hai, aur urine urethra se bahar nikal jaata hai. Roz kaafi paani peejiye, aur urine ko der tak mat rokiye. Agar kidneys kaam karna band kar dein, to ek machine blood ko saaf kar sakti hai. Ise dialysis kehte hain."))

# ================================================================ pancreas lab
part('pancreas_head', 'digestive', T("Head of the pancreas", "अग्न्याशय का सिर", "Pancreas ka head"),
  T("The wide right end of the pancreas, which sits in the C-shaped curve of the duodenum.",
    "अग्न्याशय का चौड़ा दायाँ सिरा, जो ग्रहणी (ड्यूओडेनम) के C आकार के मोड़ में टिका रहता है।",
    "Pancreas ka chauda right sira, jo duodenum ke C shape ke mod mein tika rehta hai."),
  T("The head holds the last part of the pancreatic duct and the bile duct, which pass through it and open together into the duodenum. A hook-shaped part below it, the uncinate process, wraps behind big blood vessels.",
    "सिर में अग्न्याशय की नली और पित्त नली का आख़िरी हिस्सा होता है। ये दोनों इसमें से गुज़रकर साथ में ग्रहणी में खुलती हैं। इसके नीचे एक हुक जैसा हिस्सा बड़ी रक्त वाहिकाओं के पीछे लिपटा रहता है।",
    "Head mein pancreatic duct aur bile duct ka aakhri hissa hota hai. Ye dono isse guzarkar saath mein duodenum mein khulti hain. Iske neeche ek hook jaisa hissa badi blood vessels ke peeche lipta rehta hai."))
part('pancreas_body', 'digestive', T("Body of the pancreas", "अग्न्याशय का धड़ (बॉडी)", "Pancreas ki body"),
  T("The long middle part of the pancreas, lying across the backbone behind the stomach.",
    "अग्न्याशय का लंबा बीच वाला भाग, जो आमाशय के पीछे रीढ़ के आर-पार लेटा रहता है।",
    "Pancreas ka lamba beech wala hissa, jo stomach ke peeche backbone ke aar-paar leta rehta hai."),
  T("Most of the pancreas is made of grape-like clusters of cells that make digestive juice. Scattered among them are about ten lakh tiny islands of hormone cells, the islets of Langerhans, which put insulin and glucagon straight into the blood.",
    "अग्न्याशय का ज़्यादातर भाग अंगूर के गुच्छों जैसी कोशिकाओं से बना है, जो पाचक रस बनाती हैं। इनके बीच लगभग दस लाख छोटे-छोटे द्वीप बिखरे हैं, जिन्हें लैंगरहैंस की द्वीपिकाएँ (आइलेट) कहते हैं। ये इंसुलिन और ग्लूकागॉन हार्मोन सीधे रक्त में डालती हैं।",
    "Pancreas ka zyaadatar hissa angoor ke guchhon jaisi cells se bana hai, jo digestive juice banati hain. Inke beech lagbhag das laakh chhote-chhote islands bikhre hain, jinhe islets of Langerhans kehte hain. Ye insulin aur glucagon hormones seedhe blood mein daalte hain."))
part('pancreas_tail', 'digestive', T("Tail of the pancreas", "अग्न्याशय की पूँछ", "Pancreas ki tail"),
  T("The narrow left end of the pancreas, which reaches up to the spleen.",
    "अग्न्याशय का पतला बायाँ सिरा, जो प्लीहा (स्प्लीन) तक पहुँचता है।",
    "Pancreas ka patla left sira, jo spleen tak pahunchta hai."),
  T("The tail has the most islets, so it makes a large share of the body's insulin. The pancreatic duct starts here and collects juice all along the gland on its way to the duodenum.",
    "पूँछ में सबसे ज़्यादा आइलेट होते हैं, इसलिए शरीर का काफ़ी इंसुलिन यहीं बनता है। अग्न्याशय की नली यहीं से शुरू होती है, और ग्रहणी तक जाते हुए पूरी ग्रंथि से रस इकट्ठा करती है।",
    "Tail mein sabse zyaada islets hote hain, isliye body ka kaafi insulin yahin banta hai. Pancreatic duct yahin se shuru hoti hai, aur duodenum tak jaate hue poori gland se juice ikattha karti hai."))
part('splenic_artery', 'circulatory', T("Splenic artery", "प्लीहा धमनी (स्प्लेनिक आर्टरी)", "Splenic artery"),
  T("A winding artery that carries blood to the spleen and gives small branches to the pancreas.",
    "एक टेढ़ी-मेढ़ी धमनी, जो प्लीहा तक रक्त ले जाती है और अग्न्याशय को छोटी शाखाएँ देती है।",
    "Ek tedhi-medhi artery, jo spleen tak blood le jaati hai aur pancreas ko chhoti branches deti hai."),
  T("It starts from a short trunk on the aorta and runs to the left along the top of the pancreas. Its many curves let it stretch when the stomach fills. At the spleen it splits into several branches.",
    "यह महाधमनी की एक छोटी शाखा से निकलती है और अग्न्याशय के ऊपरी किनारे के साथ बाईं ओर जाती है। इसके कई मोड़ इसे खिंचने देते हैं, जब आमाशय भरता है। प्लीहा पर पहुँचकर यह कई शाखाओं में बँट जाती है।",
    "Ye aorta ki ek chhoti branch se nikalti hai aur pancreas ke upar wale kinaare ke saath left ki taraf jaati hai. Iske kai mod ise khinchne dete hain, jab stomach bharta hai. Spleen par pahunchkar ye kai branches mein bant jaati hai."))
part('splenic_vein', 'circulatory', T("Splenic vein", "प्लीहा शिरा (स्प्लेनिक वेन)", "Splenic vein"),
  T("Carries blood from the spleen and pancreas, with insulin in it, to the portal vein and the liver.",
    "प्लीहा और अग्न्याशय से रक्त, इंसुलिन के साथ, निर्वाहिका शिरा (पोर्टल वेन) और लिवर तक ले जाती है।",
    "Spleen aur pancreas se blood, insulin ke saath, portal vein aur liver tak le jaati hai."),
  T("It runs behind the pancreas and collects many small veins from it. So insulin made in the islets reaches the liver first, where it tells the liver to store extra sugar. Then the blood goes on to the heart and the whole body.",
    "यह अग्न्याशय के पीछे चलती है और उससे कई छोटी शिराएँ इकट्ठा करती है। इसलिए आइलेट में बना इंसुलिन सबसे पहले लिवर तक पहुँचता है, और लिवर से ज़्यादा शक्कर जमा करने को कहता है। फिर रक्त हृदय और पूरे शरीर तक जाता है।",
    "Ye pancreas ke peeche chalti hai aur usse kai chhoti veins ikattha karti hai. Isliye islets mein bana insulin sabse pehle liver tak pahunchta hai, aur liver se extra sugar store karne ko kehta hai. Phir blood heart aur poori body tak jaata hai."))
part('portal_vein', 'circulatory', T("Portal vein", "निर्वाहिका शिरा (पोर्टल वेन)", "Portal vein"),
  T("Carries blood rich in digested food from the intestines, and blood from the spleen and pancreas, to the liver.",
    "आँतों से पचे हुए भोजन वाला रक्त, और प्लीहा तथा अग्न्याशय का रक्त, लिवर तक ले जाती है।",
    "Intestines se pache hue khaane wala blood, aur spleen tathaa pancreas ka blood, liver tak le jaati hai."),
  T("It forms behind the neck of the pancreas, where the splenic vein meets the vein from the small intestine. In the liver, the nutrients are stored or changed, and harmful substances are removed, before the blood goes to the heart.",
    "यह अग्न्याशय की गर्दन के पीछे बनती है, जहाँ प्लीहा शिरा छोटी आँत की शिरा से मिलती है। लिवर में पोषक तत्व जमा किए जाते हैं या बदले जाते हैं, और हानिकारक पदार्थ हटाए जाते हैं। उसके बाद ही रक्त हृदय तक जाता है।",
    "Ye pancreas ki gardan ke peeche banti hai, jahan splenic vein small intestine ki vein se milti hai. Liver mein nutrients store kiye jaate hain ya badle jaate hain, aur harmful cheezein hataayi jaati hain. Uske baad hi blood heart tak jaata hai."))
step('lab-pancreas-1', T("Pancreas and spleen: two neighbours", "अग्न्याशय और प्लीहा: दो पड़ोसी", "Pancreas aur spleen: do padosi"),
  T("Behind the stomach lies a long, soft gland, the pancreas. Its head sits in the C-shaped curve of the duodenum, and its tail reaches the spleen on the left. The pancreas helps in two ways: it makes digestive juice, and it makes hormones like insulin. The spleen is a dark red organ that filters the blood.",
    "आमाशय के पीछे एक लंबी, नरम ग्रंथि होती है, अग्न्याशय (पैंक्रियास)। इसका सिर ग्रहणी के C आकार के मोड़ में टिका है, और इसकी पूँछ बाईं ओर प्लीहा तक पहुँचती है। अग्न्याशय दो तरह से मदद करता है: यह पाचक रस बनाता है, और इंसुलिन जैसे हार्मोन भी बनाता है। प्लीहा (स्प्लीन) गहरे लाल रंग का अंग है, जो रक्त को छानता है।",
    "Stomach ke peeche ek lambi, naram gland hoti hai, pancreas. Iska head duodenum ke C shape ke mod mein tika hai, aur iski tail left taraf spleen tak pahunchti hai. Pancreas do tarah se help karta hai: ye digestive juice banata hai, aur insulin jaise hormones bhi banata hai. Spleen gehre laal rang ka organ hai, jo blood ko chhaanta hai."))
step('lab-pancreas-2', T("Head, body and tail", "सिर, धड़ और पूँछ", "Head, body aur tail"),
  T("The pancreas is about 15 centimetres long and shaped a bit like a fish. The wide head is on the right, in the curve of the duodenum. The long body crosses the backbone, and the thin tail ends near the spleen. It is soft, and made of tiny grape-like bunches of cells.",
    "अग्न्याशय लगभग पंद्रह सेंटीमीटर लंबा होता है, और इसका आकार कुछ-कुछ मछली जैसा होता है। चौड़ा सिर दाईं ओर, ग्रहणी के मोड़ में है। लंबा धड़ रीढ़ की हड्डी के आर-पार जाता है, और पतली पूँछ प्लीहा के पास ख़त्म होती है। यह नरम होता है, और अंगूर जैसे कोशिकाओं के छोटे-छोटे गुच्छों से बना होता है।",
    "Pancreas lagbhag pandrah centimetre lamba hota hai, aur iska aakaar kuch-kuch machhli jaisa hota hai. Chauda head right taraf, duodenum ke mod mein hai. Lambi body backbone ke aar-paar jaati hai, aur patli tail spleen ke paas khatam hoti hai. Ye naram hota hai, aur angoor jaise cells ke chhote-chhote guchhon se bana hota hai."))
step('lab-pancreas-3', T("Pancreatic juice", "अग्न्याशय रस", "Pancreatic juice"),
  T("Look through the pancreas: a duct runs along its whole length. It collects pancreatic juice, about one and a half litres a day, and carries it to the duodenum. Just before the end it joins the bile duct from the liver and gallbladder. The juice has enzymes for every kind of food: amylase for starch, trypsin for proteins and lipase for fats.",
    "अग्न्याशय के आर-पार देखिए: इसकी पूरी लंबाई में एक नली चलती है। यह अग्न्याशय रस इकट्ठा करती है, दिन भर में लगभग डेढ़ लीटर, और उसे ग्रहणी तक ले जाती है। आख़िर में पहुँचने से ठीक पहले यह लिवर और पित्ताशय से आने वाली पित्त नली से मिल जाती है। इस रस में हर तरह के भोजन के एंजाइम होते हैं: स्टार्च के लिए एमाइलेज़, प्रोटीन के लिए ट्रिप्सिन, और वसा (फ़ैट) के लिए लाइपेज़।",
    "Pancreas ke aar-paar dekhiye: iski poori lambaai mein ek duct chalti hai. Ye pancreatic juice ikattha karti hai, din bhar mein lagbhag dedh litre, aur use duodenum tak le jaati hai. End se theek pehle ye liver aur gallbladder se aane wali bile duct se mil jaati hai. Is juice mein har tarah ke khaane ke enzymes hote hain: starch ke liye amylase, protein ke liye trypsin, aur fat ke liye lipase."))
step('lab-pancreas-4', T("Islets make insulin", "आइलेट इंसुलिन बनाते हैं", "Islets insulin banate hain"),
  T("Scattered through the pancreas are tiny islands of cells, the islets. They make hormones and put them straight into the blood, not into the duct. After a meal, blood sugar rises, and beta cells release insulin. Insulin lets sugar enter the body's cells to give energy, and tells the liver to store the extra. If the body has too little insulin, blood sugar stays high. This is diabetes.",
    "अग्न्याशय में कोशिकाओं के छोटे-छोटे द्वीप बिखरे हैं, जिन्हें आइलेट कहते हैं। ये हार्मोन बनाते हैं और उन्हें नली में नहीं, सीधे रक्त में डालते हैं। खाना खाने के बाद रक्त में शक्कर बढ़ती है, तो बीटा कोशिकाएँ इंसुलिन छोड़ती हैं। इंसुलिन शक्कर को शरीर की कोशिकाओं में जाने देता है, ताकि ऊर्जा मिले, और लिवर से कहता है कि बची हुई शक्कर जमा कर ले। अगर शरीर में इंसुलिन बहुत कम हो, तो रक्त में शक्कर ज़्यादा ही बनी रहती है। इसी को मधुमेह (डायबिटीज़) कहते हैं।",
    "Pancreas mein cells ke chhote-chhote islands bikhre hain, jinhe islets kehte hain. Ye hormones banate hain aur unhe duct mein nahi, seedhe blood mein daalte hain. Khaana khaane ke baad blood mein sugar badhti hai, to beta cells insulin chhodti hain. Insulin sugar ko body ki cells mein jaane deta hai, taaki energy mile, aur liver se kehta hai ki bachi hui sugar store kar le. Agar body mein insulin bahut kam ho, to blood mein sugar zyaada hi bani rehti hai. Isi ko diabetes kehte hain."))
step('lab-pancreas-5', T("The spleen: a blood filter", "प्लीहा: रक्त की छलनी", "Spleen: blood ki chhalni"),
  T("The spleen is about the size of your fist and sits on the left, under the ribs. Blood comes in through the winding splenic artery. Inside, old and worn-out red blood cells are broken down, and their iron is saved. White blood cells in the spleen catch germs and help fight infection. The blood leaves through the splenic vein.",
    "प्लीहा लगभग आपकी मुट्ठी जितनी बड़ी होती है, और बाईं ओर पसलियों के नीचे रहती है। रक्त टेढ़ी-मेढ़ी प्लीहा धमनी से अंदर आता है। अंदर पुरानी और घिसी हुई लाल रक्त कोशिकाएँ तोड़ी जाती हैं, और उनका लोहा (आयरन) बचा लिया जाता है। प्लीहा की श्वेत रक्त कोशिकाएँ कीटाणुओं को पकड़ती हैं, और संक्रमण से लड़ने में मदद करती हैं। रक्त प्लीहा शिरा से बाहर निकलता है।",
    "Spleen lagbhag aapki mutthi jitni badi hoti hai, aur left taraf ribs ke neeche rehti hai. Blood tedhi-medhi splenic artery se andar aata hai. Andar puraani aur ghisi hui red blood cells todi jaati hain, aur unka iron bacha liya jaata hai. Spleen ki white blood cells germs ko pakadti hain, aur infection se ladne mein help karti hain. Blood splenic vein se bahar nikalta hai."))
step('lab-pancreas-6', T("Working together", "मिलकर काम", "Milkar kaam"),
  T("Blood from the spleen and pancreas, carrying insulin, joins the blood from the intestines in the portal vein and goes to the liver. So the liver gets food, insulin and recycled iron together. Help your pancreas: eat less sugar and junk food, eat whole grains, fruits and vegetables, and play or exercise every day.",
    "प्लीहा और अग्न्याशय का रक्त, इंसुलिन के साथ, निर्वाहिका शिरा (पोर्टल वेन) में आँतों के रक्त से मिलता है और लिवर तक जाता है। इस तरह लिवर को भोजन, इंसुलिन और बचाया हुआ लोहा, सब एक साथ मिलता है। अपने अग्न्याशय की मदद कीजिए: कम मीठा और कम जंक फ़ूड खाइए, साबुत अनाज, फल और सब्ज़ियाँ खाइए, और रोज़ खेलिए या व्यायाम कीजिए।",
    "Spleen aur pancreas ka blood, insulin ke saath, portal vein mein intestines ke blood se milta hai aur liver tak jaata hai. Is tarah liver ko khaana, insulin aur bachaaya hua iron, sab ek saath milta hai. Apne pancreas ki help kijiye: kam meetha aur kam junk food khaaiye, whole grains, fruits aur sabziyaan khaaiye, aur roz kheliye ya exercise kijiye."))

# ================================================================ journeys (en mirrors body/js/journeys_new.js)
JT['reflex'] = T("Reflex: the quick escape", "प्रतिवर्ती क्रिया: झटपट बचाव", "Reflex: jhatpat bachaav")
JT['hormones'] = T("Hormones: chemical messages", "हार्मोन: रासायनिक संदेश", "Hormones: chemical messages")
step('reflex-1', T("Ouch, a hot tawa!", "आउच, गरम तवा!", "Ouch, garam tawa!"),
  T("Imagine your fingertips touch a hot tawa. In the skin there are tiny sense cells, called receptors, for heat, touch and pain. The heat receptors fire at once and start an electric signal in a nerve.",
    "सोचिए, आपकी उँगलियाँ गरम तवे से छू गईं। त्वचा में छोटी-छोटी संवेदी कोशिकाएँ होती हैं, जिन्हें ग्राही (रिसेप्टर) कहते हैं। ये गर्मी, छूने और दर्द को पहचानती हैं। गर्मी वाले ग्राही तुरंत जाग जाते हैं, और तंत्रिका में एक विद्युत संकेत शुरू कर देते हैं।",
    "Sochiye, aapki ungliyaan garam tawe se chhoo gayin. Skin mein chhote-chhote sense cells hote hain, jinhe receptors kehte hain. Ye garmi, touch aur dard ko pehchaante hain. Garmi wale receptors turant jaag jaate hain, aur nerve mein ek electric signal shuru kar dete hain."))
step('reflex-2', T("Up the sensory nerve", "संवेदी तंत्रिका से ऊपर", "Sensory nerve se upar"),
  T("The signal races up the arm in a sensory nerve, faster than a train, at about 100 metres every second. It enters the spinal cord in the neck, through the back root of a spinal nerve.",
    "संकेत संवेदी तंत्रिका में बाँह से ऊपर दौड़ता है, रेलगाड़ी से भी तेज़, लगभग सौ मीटर हर सेकंड। यह मेरु तंत्रिका की पिछली जड़ से होकर गर्दन में मेरुरज्जु के अंदर पहुँचता है।",
    "Signal sensory nerve mein arm se upar daudta hai, train se bhi tez, lagbhag sau metre har second. Ye spinal nerve ki peeche wali root se hokar gardan mein spinal cord ke andar pahunchta hai."))
step('reflex-3', T("The spinal cord decides", "मेरुरज्जु फ़ैसला करता है", "Spinal cord decide karta hai"),
  T("Inside the spinal cord, the sensory neuron passes the signal to a small relay neuron, and the relay neuron passes it straight to a motor neuron. The spinal cord gives the order by itself. It does not wait for the brain, because waiting could mean a bad burn.",
    "मेरुरज्जु के अंदर संवेदी न्यूरॉन संकेत एक छोटे रिले न्यूरॉन को देता है, और रिले न्यूरॉन उसे सीधे प्रेरक न्यूरॉन (मोटर न्यूरॉन) को दे देता है। मेरुरज्जु ख़ुद ही आदेश दे देता है। यह मस्तिष्क का इंतज़ार नहीं करता, क्योंकि इंतज़ार करने में हाथ बुरी तरह जल सकता है।",
    "Spinal cord ke andar sensory neuron signal ek chhote relay neuron ko deta hai, aur relay neuron use seedhe motor neuron ko de deta hai. Spinal cord khud hi order de deta hai. Ye brain ka intezaar nahi karta, kyunki intezaar karne mein haath buri tarah jal sakta hai."))
step('reflex-4', T("The muscle pulls the hand away", "मांसपेशी हाथ खींच लेती है", "Muscle haath kheench leti hai"),
  T("The motor nerve carries the order to the muscles of the arm. The biceps contracts and the hand jumps away from the tawa. From touch to escape takes only a few hundredths of a second, quicker than a blink.",
    "प्रेरक तंत्रिका यह आदेश बाँह की मांसपेशियों तक ले जाती है। बाइसेप्स सिकुड़ती है, और हाथ झटके से तवे से हट जाता है। छूने से बचने तक, बस सेकंड के कुछ सौवें हिस्से लगते हैं, पलक झपकने से भी कम!",
    "Motor nerve ye order arm ki muscles tak le jaati hai. Biceps contract hoti hai, aur haath jhatke se tawe se hat jaata hai. Chhoone se bachne tak, bas second ke kuch sauvein hisse lagte hain, palak jhapakne se bhi kam!"))
step('reflex-5', T("Then the brain feels it", "फिर मस्तिष्क को पता चलता है", "Phir brain ko pata chalta hai"),
  T("The signal also travels up the spinal cord to the brain. Only when it reaches the brain do you feel the pain and say Ouch! By then your hand is already safe. The brain also remembers, so next time you are more careful near a hot tawa.",
    "संकेत मेरुरज्जु से ऊपर मस्तिष्क तक भी जाता है। जब यह मस्तिष्क तक पहुँचता है, तभी आपको दर्द महसूस होता है, और आप कहते हैं, आउच! तब तक आपका हाथ बच चुका होता है। मस्तिष्क इसे याद भी रखता है, इसलिए अगली बार आप गरम तवे के पास ज़्यादा ध्यान रखते हैं।",
    "Signal spinal cord se upar brain tak bhi jaata hai. Jab ye brain tak pahunchta hai, tabhi aapko dard feel hota hai, aur aap kehte hain, Ouch! Tab tak aapka haath bach chuka hota hai. Brain ise yaad bhi rakhta hai, isliye agli baar aap garam tawe ke paas zyaada dhyaan rakhte hain."))
step('reflex-6', T("Reflexes keep us safe", "प्रतिवर्ती क्रियाएँ हमें बचाती हैं", "Reflexes humein bachaate hain"),
  T("This path, from the receptor to the sensory neuron, the relay neuron, the motor neuron and the muscle, is called a reflex arc. Blinking when something comes near the eye, sneezing, coughing and the knee jerk are reflexes too. To watch the arm pull back, open the Organ Lab: Arm muscles and reflex.",
    "ग्राही से संवेदी न्यूरॉन, रिले न्यूरॉन, प्रेरक न्यूरॉन और मांसपेशी तक के इस रास्ते को प्रतिवर्ती चाप (रिफ़्लेक्स आर्क) कहते हैं। आँख के पास कुछ आने पर पलक झपकना, छींकना, खाँसना और घुटने का झटका भी प्रतिवर्ती क्रियाएँ हैं। बाँह को पीछे खिंचते हुए देखने के लिए, अंग प्रयोगशाला में बाँह की मांसपेशियाँ और प्रतिवर्त खोलिए।",
    "Receptor se sensory neuron, relay neuron, motor neuron aur muscle tak ke is raaste ko reflex arc kehte hain. Aankh ke paas kuch aane par palak jhapakna, chheenkna, khaansna aur knee jerk bhi reflexes hain. Arm ko peeche khinchte hue dekhne ke liye, Organ Lab mein Arm muscles aur reflex kholiye."))
step('hormones-1', T("Chemical messengers", "रासायनिक संदेशवाहक", "Chemical messengers"),
  T("Nerves send quick electric messages. The body also sends slower chemical messages, called hormones. They are made by endocrine glands, which pour them straight into the blood, without any tube. The blood carries them everywhere, but each hormone works only on its own target organs.",
    "तंत्रिकाएँ तेज़ विद्युत संदेश भेजती हैं। शरीर धीमे रासायनिक संदेश भी भेजता है, जिन्हें हार्मोन कहते हैं। इन्हें अंतःस्रावी ग्रंथियाँ (एंडोक्राइन ग्लैंड) बनाती हैं, और बिना किसी नली के, सीधे रक्त में डाल देती हैं। रक्त इन्हें हर जगह ले जाता है, पर हर हार्मोन सिर्फ़ अपने लक्ष्य अंगों पर ही काम करता है।",
    "Nerves tez electric messages bhejti hain. Body dheere chemical messages bhi bhejti hai, jinhe hormones kehte hain. Inhe endocrine glands banati hain, aur bina kisi nali ke, seedhe blood mein daal deti hain. Blood inhe har jagah le jaata hai, par har hormone sirf apne target organs par hi kaam karta hai."))
step('hormones-2', T("Pituitary: the master gland", "पीयूष ग्रंथि: मास्टर ग्रंथि", "Pituitary: master gland"),
  T("Under the brain hangs a gland the size of a pea, the pituitary. The hypothalamus of the brain above it tells it what to do. It makes growth hormone, which helps the body and bones grow. Too little in childhood makes a person very short, and too much makes them very tall. It also controls many other glands, so it is called the master gland.",
    "मस्तिष्क के नीचे मटर के दाने जितनी एक ग्रंथि लटकी रहती है, पीयूष ग्रंथि (पिट्यूटरी)। इसके ऊपर मस्तिष्क का हाइपोथैलेमस इसे बताता है कि क्या करना है। यह वृद्धि हार्मोन (ग्रोथ हार्मोन) बनाती है, जिससे शरीर और हड्डियाँ बढ़ती हैं। बचपन में यह बहुत कम बने, तो व्यक्ति बहुत छोटे क़द का रह जाता है, और बहुत ज़्यादा बने, तो बहुत लंबा हो जाता है। यह कई दूसरी ग्रंथियों को भी चलाती है, इसलिए इसे मास्टर ग्रंथि कहते हैं।",
    "Brain ke neeche matar ke daane jitni ek gland latki rehti hai, pituitary. Iske upar brain ka hypothalamus ise batata hai ki kya karna hai. Ye growth hormone banati hai, jisse body aur haddiyaan badhti hain. Bachpan mein ye bahut kam bane, to insaan bahut chhote kad ka reh jaata hai, aur bahut zyaada bane, to bahut lamba ho jaata hai. Ye kai doosri glands ko bhi chalaati hai, isliye ise master gland kehte hain."))
step('hormones-3', T("Thyroid: the body's speed control", "थायरॉइड: शरीर की रफ़्तार का नियंत्रक", "Thyroid: body ki speed control"),
  T("The thyroid is a butterfly-shaped gland in the front of the neck. Its hormone, thyroxine, controls how fast the body uses food for energy. To make thyroxine, the thyroid needs iodine. Without enough iodine the neck swells. This is called goitre. That is why we use iodised salt.",
    "थायरॉइड गर्दन के आगे तितली के आकार की एक ग्रंथि है। इसका हार्मोन, थायरॉक्सिन, तय करता है कि शरीर भोजन से ऊर्जा कितनी तेज़ी से बनाए। थायरॉक्सिन बनाने के लिए थायरॉइड को आयोडीन चाहिए। आयोडीन कम हो, तो गर्दन फूल जाती है। इसे घेंघा (गॉयटर) कहते हैं। इसीलिए हम आयोडीन वाला नमक खाते हैं।",
    "Thyroid gardan ke aage titli ke aakaar ki ek gland hai. Iska hormone, thyroxine, tay karta hai ki body khaane se energy kitni tezi se banaye. Thyroxine banane ke liye thyroid ko iodine chahiye. Iodine kam ho, to gardan phool jaati hai. Ise goitre kehte hain. Isiliye hum iodised salt khaate hain."))
step('hormones-4', T("Adrenal glands: ready for action", "अधिवृक्क ग्रंथियाँ: काम के लिए तैयार", "Adrenal glands: action ke liye ready"),
  T("On top of each kidney sits an adrenal gland. When you are scared, or a dog suddenly chases you, they release adrenaline into the blood. The heart beats faster, you breathe faster, and more blood rushes to the muscles. The body is ready to run or to fight.",
    "हर गुर्दे के ऊपर एक अधिवृक्क ग्रंथि (एड्रिनल ग्लैंड) बैठी होती है। जब आप डरते हैं, या अचानक कोई कुत्ता आपके पीछे दौड़ता है, तो ये रक्त में एड्रिनलिन छोड़ती हैं। दिल तेज़ धड़कने लगता है, साँस तेज़ हो जाती है, और मांसपेशियों तक ज़्यादा रक्त पहुँचता है। शरीर भागने या लड़ने के लिए तैयार हो जाता है।",
    "Har kidney ke upar ek adrenal gland baithi hoti hai. Jab aap darte hain, ya achaanak koi kutta aapke peeche daudta hai, to ye blood mein adrenaline chhodti hain. Dil tez dhadakne lagta hai, saans tez ho jaati hai, aur muscles tak zyaada blood pahunchta hai. Body bhaagne ya ladne ke liye ready ho jaati hai."))
step('hormones-5', T("Pancreas: the sugar balance", "अग्न्याशय: शक्कर का संतुलन", "Pancreas: sugar ka balance"),
  T("Tiny islets in the pancreas make insulin. After a meal, insulin helps sugar from the blood enter the cells, and tells the liver to store the extra. Between meals another hormone, glucagon, lets the liver release sugar again. If too little insulin is made, sugar stays high in the blood. This is diabetes.",
    "अग्न्याशय के छोटे-छोटे आइलेट इंसुलिन बनाते हैं। खाने के बाद इंसुलिन रक्त की शक्कर को कोशिकाओं में जाने में मदद करता है, और लिवर से कहता है कि बची हुई शक्कर जमा कर ले। दो खानों के बीच एक दूसरा हार्मोन, ग्लूकागॉन, लिवर से फिर शक्कर निकलवाता है। अगर इंसुलिन कम बने, तो रक्त में शक्कर ज़्यादा बनी रहती है। यही मधुमेह (डायबिटीज़) है।",
    "Pancreas ke chhote-chhote islets insulin banate hain. Khaane ke baad insulin blood ki sugar ko cells mein jaane mein help karta hai, aur liver se kehta hai ki bachi hui sugar store kar le. Do khaanon ke beech ek doosra hormone, glucagon, liver se phir sugar nikalwata hai. Agar insulin kam bane, to blood mein sugar zyaada bani rehti hai. Yahi diabetes hai."))
step('hormones-6', T("Growing up", "बड़े होना", "Bade hona"),
  T("Between about 10 and 14 years of age, the pituitary tells the testes in boys to make testosterone, and the ovaries in girls to make oestrogen. These hormones bring the changes of growing up, called puberty: a growth spurt, a deeper voice in boys, and more. These changes are natural, and they come at different ages for different children.",
    "लगभग दस से चौदह साल की उम्र के बीच, पीयूष ग्रंथि लड़कों में वृषण (टेस्टिस) को टेस्टोस्टेरॉन बनाने को कहती है, और लड़कियों में अंडाशय (ओवरी) को एस्ट्रोजन बनाने को। ये हार्मोन बड़े होने के बदलाव लाते हैं, जिसे यौवनारंभ (प्यूबर्टी) कहते हैं: अचानक क़द बढ़ना, लड़कों की आवाज़ भारी होना, और भी बहुत कुछ। ये बदलाव प्राकृतिक हैं, और अलग-अलग बच्चों में अलग-अलग उम्र में आते हैं।",
    "Lagbhag das se chaudah saal ki umar ke beech, pituitary ladkon mein testes ko testosterone banane ko kehti hai, aur ladkiyon mein ovaries ko oestrogen banane ko. Ye hormones bade hone ke badlaav laate hain, jise puberty kehte hain: achaanak kad badhna, ladkon ki awaaz bhaari hona, aur bhi bahut kuch. Ye badlaav natural hain, aur alag-alag bachchon mein alag-alag umar mein aate hain."))
step('hormones-7', T("Just the right amount", "बिल्कुल सही मात्रा", "Bilkul sahi amount"),
  T("Hormones must be made in just the right amount. The body checks and corrects itself: when blood sugar goes up, the pancreas makes more insulin, and when sugar comes down, it makes less. This is called feedback. A balanced diet with iodised salt, enough sleep and daily play keep your glands healthy.",
    "हार्मोन बिल्कुल सही मात्रा में बनने चाहिए। शरीर ख़ुद जाँचता और सुधारता रहता है: रक्त में शक्कर बढ़े, तो अग्न्याशय ज़्यादा इंसुलिन बनाता है, और शक्कर घटे, तो कम। इसे प्रतिपुष्टि (फ़ीडबैक) कहते हैं। आयोडीन वाले नमक के साथ संतुलित भोजन, पूरी नींद और रोज़ खेलना, आपकी ग्रंथियों को स्वस्थ रखते हैं।",
    "Hormones bilkul sahi amount mein banne chahiye. Body khud check aur correct karti rehti hai: blood mein sugar badhe, to pancreas zyaada insulin banata hai, aur sugar ghate, to kam. Ise feedback kehte hain. Iodised salt ke saath balanced diet, poori neend aur roz khelna, aapki glands ko healthy rakhte hain."))

# ================================================================ leg lab (knee extension, knee jerk)
part('knee_joint', 'skeleton', T("Knee joint (hinge joint)", "घुटने का जोड़ (कब्ज़ा जोड़)", "Knee joint (hinge joint)"),
  T("Where the thigh bone meets the shin bone; it lets the leg bend and straighten and carries the body's weight.",
    "जहाँ जाँघ की हड्डी पिंडली की हड्डी से मिलती है; यह टाँग को मुड़ने और सीधा होने देता है, और शरीर का भार उठाता है।",
    "Jahan thigh bone shin bone se milti hai; ye leg ko mudne aur seedha hone deta hai, aur body ka weight uthata hai."),
  T("The rounded knuckles of the femur roll and glide on the flat top of the tibia, cushioned by two pads of cartilage. Strong ligaments hold the bones together, so the knee bends mostly in one direction, like a hinge. The kneecap slides in a groove at the front.",
    "फ़ीमर के गोल उभार टिबिया के सपाट ऊपरी हिस्से पर लुढ़कते और फिसलते हैं, और उपास्थि (कार्टिलेज) की दो गद्दियाँ झटका सोखती हैं। मज़बूत स्नायु (लिगामेंट) हड्डियों को बाँधे रखते हैं, इसलिए घुटना कब्ज़े की तरह ज़्यादातर एक ही दिशा में मुड़ता है। आगे की ओर घुटने की टोपी एक खाँचे में फिसलती है।",
    "Femur ke gol ubhaar tibia ke flat upar wale hisse par ludhakte aur phisalte hain, aur cartilage ki do gaddiyaan jhatka sokhti hain. Mazboot ligaments haddiyon ko baandhe rakhte hain, isliye knee hinge ki tarah zyaadatar ek hi direction mein mudta hai. Aage ki taraf kneecap ek khaanche mein phisalti hai."))
part('patellar_ligament', 'muscles', T("Patellar tendon", "पटेला कंडरा (घुटने की टोपी की कंडरा)", "Patellar tendon"),
  T("The strong band from the kneecap to the shin bone, through which the quadriceps pulls to straighten the knee.",
    "घुटने की टोपी से पिंडली की हड्डी तक की मज़बूत पट्टी, जिससे होकर क्वाड्रिसेप्स घुटने को सीधा करने के लिए खींचती है।",
    "Kneecap se shin bone tak ki mazboot patti, jisse hokar quadriceps knee ko seedha karne ke liye kheenchti hai."),
  T("The four parts of the quadriceps join into one tendon that holds the kneecap, and continue below it as this band to a bump on the front of the tibia. When a doctor taps it with a small hammer, the muscle is stretched for a moment, and the knee-jerk reflex makes the leg kick.",
    "क्वाड्रिसेप्स के चारों भाग मिलकर एक कंडरा बनाते हैं, जो घुटने की टोपी को थामे रहती है, और उसके नीचे यही पट्टी बनकर टिबिया के आगे के एक उभार तक जाती है। जब डॉक्टर इस पर छोटे हथौड़े से ठोकते हैं, तो मांसपेशी एक पल के लिए खिंचती है, और घुटने का झटका (नी-जर्क) प्रतिवर्त टाँग को आगे उछाल देता है।",
    "Quadriceps ke chaaron hisse milkar ek tendon banate hain, jo kneecap ko thaame rehta hai, aur uske neeche yahi patti bankar tibia ke aage ke ek ubhaar tak jaata hai. Jab doctor is par chhote hammer se tap karte hain, to muscle ek pal ke liye khinchti hai, aur knee-jerk reflex leg ko aage uchhaal deta hai."))
step('lab-leg-1', T("The leg: thigh and calf muscles", "टाँग: जाँघ और पिंडली की मांसपेशियाँ", "Leg: thigh aur calf ki muscles"),
  T("This is a real right leg. The thigh has one strong bone, the femur, the longest bone of the body. Below the knee are the tibia and the thin fibula. The big muscle in front of the thigh is the quadriceps, made of four parts. At the back of the thigh are the hamstrings, and the calf muscle sits behind the shin.",
    "यह असली जैसी दाईं टाँग है। जाँघ में एक मज़बूत हड्डी है, फ़ीमर, जो शरीर की सबसे लंबी हड्डी है। घुटने के नीचे टिबिया और पतली फ़िबुला हैं। जाँघ के आगे की बड़ी मांसपेशी क्वाड्रिसेप्स है, जो चार भागों से बनी है। जाँघ के पीछे हैमस्ट्रिंग हैं, और पिंडली के पीछे पिंडली की मांसपेशी (काफ़ मसल) है।",
    "Ye asli jaisi right leg hai. Thigh mein ek mazboot haddi hai, femur, jo body ki sabse lambi haddi hai. Knee ke neeche tibia aur patli fibula hain. Thigh ke aage ki badi muscle quadriceps hai, jo chaar hisson se bani hai. Thigh ke peeche hamstrings hain, aur shin ke peeche calf muscle hai."))
step('lab-leg-2', T("The hamstrings bend the knee", "हैमस्ट्रिंग घुटना मोड़ती हैं", "Hamstrings knee modti hain"),
  T("Watch the back of the thigh. The hamstrings start on the hip bone and are tied below the knee to the tibia and fibula. When they contract, they get shorter and pull the shin back, so the knee bends. At the same time the quadriceps in front relaxes and is stretched.",
    "जाँघ के पीछे देखिए। हैमस्ट्रिंग कूल्हे की हड्डी से शुरू होती हैं, और घुटने के नीचे टिबिया और फ़िबुला से बँधी हैं। जब ये सिकुड़ती हैं, तो छोटी हो जाती हैं और पिंडली को पीछे खींचती हैं, इसलिए घुटना मुड़ता है। उसी समय आगे की क्वाड्रिसेप्स ढीली होकर खिंच जाती है।",
    "Thigh ke peeche dekhiye. Hamstrings hip bone se shuru hoti hain, aur knee ke neeche tibia aur fibula se bandhi hain. Jab ye contract hoti hain, to chhoti ho jaati hain aur shin ko peeche kheenchti hain, isliye knee mudta hai. Usi samay aage ki quadriceps relax hokar khinch jaati hai."))
step('lab-leg-3', T("The quadriceps straightens the knee", "क्वाड्रिसेप्स घुटना सीधा करती है", "Quadriceps knee seedha karti hai"),
  T("To straighten the knee, the quadriceps contracts and the hamstrings relax. The quadriceps pulls on the kneecap, and the kneecap's tendon pulls the shin forward. This is knee extension, the movement we use to stand up, climb stairs and kick a football. Here again two muscles work as a pair.",
    "घुटने को सीधा करने के लिए क्वाड्रिसेप्स सिकुड़ती है, और हैमस्ट्रिंग ढीली हो जाती हैं। क्वाड्रिसेप्स घुटने की टोपी को खींचती है, और टोपी की कंडरा पिंडली को आगे खींचती है। इसे घुटने का फैलाव (नी एक्सटेंशन) कहते हैं। खड़े होने, सीढ़ियाँ चढ़ने और फ़ुटबॉल को किक मारने में हम यही करते हैं। यहाँ भी दो मांसपेशियाँ जोड़ी में काम करती हैं।",
    "Knee ko seedha karne ke liye quadriceps contract hoti hai, aur hamstrings relax ho jaati hain. Quadriceps kneecap ko kheenchti hai, aur kneecap ka tendon shin ko aage kheenchta hai. Ise knee extension kehte hain. Khade hone, seedhiyaan chadhne aur football ko kick maarne mein hum yahi karte hain. Yahan bhi do muscles pair mein kaam karti hain."))
step('lab-leg-4', T("The kneecap: a pulley", "घुटने की टोपी: एक घिरनी", "Kneecap: ek pulley"),
  T("The kneecap, or patella, sits inside the tendon of the quadriceps, in front of the knee. As the knee bends, it slides down a groove in the femur. Like a pulley, it lifts the tendon away from the joint, so the quadriceps can pull with more force. It also shields the front of the knee.",
    "घुटने की टोपी, यानी पटेला, घुटने के आगे क्वाड्रिसेप्स की कंडरा के अंदर रहती है। घुटना मुड़ने पर यह फ़ीमर के एक खाँचे में नीचे फिसलती है। एक घिरनी की तरह यह कंडरा को जोड़ से थोड़ा दूर उठाए रखती है, ताकि क्वाड्रिसेप्स ज़्यादा ताक़त से खींच सके। यह घुटने के आगे के हिस्से की रक्षा भी करती है।",
    "Kneecap, yaani patella, knee ke aage quadriceps ke tendon ke andar rehti hai. Knee mudne par ye femur ke ek khaanche mein neeche phisalti hai. Ek pulley ki tarah ye tendon ko joint se thoda door uthaaye rakhti hai, taaki quadriceps zyaada taakat se kheench sake. Ye knee ke aage ke hisse ki raksha bhi karti hai."))
step('lab-leg-5', T("The knee-jerk reflex", "घुटने का झटका: एक प्रतिवर्त", "Knee-jerk reflex"),
  T("Now the leg hangs from the edge of a table. The doctor taps the tendon just below the kneecap. The tap stretches the quadriceps for a moment. Stretch sensors in the muscle send a signal up the sensory nerve to the spinal cord, which sends it straight back down a motor nerve. The quadriceps contracts and the leg kicks forward by itself! Doctors use this test to check that the nerves and spinal cord work well.",
    "अब टाँग मेज़ के किनारे से लटक रही है। डॉक्टर घुटने की टोपी के ठीक नीचे की कंडरा पर हल्के से ठोकते हैं। इससे क्वाड्रिसेप्स एक पल के लिए खिंचती है। मांसपेशी में खिंचाव पहचानने वाले ग्राही संवेदी तंत्रिका से मेरुरज्जु तक संकेत भेजते हैं, और मेरुरज्जु उसे सीधे प्रेरक तंत्रिका से वापस भेज देता है। क्वाड्रिसेप्स सिकुड़ती है, और टाँग अपने-आप आगे उछल जाती है! डॉक्टर इस जाँच से देखते हैं कि तंत्रिकाएँ और मेरुरज्जु ठीक काम कर रहे हैं।",
    "Ab leg table ke kinaare se latak rahi hai. Doctor kneecap ke theek neeche ke tendon par halke se tap karte hain. Isse quadriceps ek pal ke liye khinchti hai. Muscle mein stretch pehchaanne wale sensors sensory nerve se spinal cord tak signal bhejte hain, aur spinal cord use seedhe motor nerve se wapas bhej deta hai. Quadriceps contract hoti hai, aur leg apne-aap aage uchhal jaati hai! Doctor is test se dekhte hain ki nerves aur spinal cord theek kaam kar rahe hain."))


def apply():
    c = json.load(open(f'{APP}/models/content.json'))
    import os
    mine_f = '/root/work/labs3/added_parts.json'; mine = set(json.load(open(mine_f))) if os.path.exists(mine_f) else set()
    added = []
    for k, v in P.items():
        if k in c['parts'] and k not in mine: print('exists, kept:', k); continue
        c['parts'][k] = v; added.append(k); mine.add(k)
    json.dump(sorted(mine), open(mine_f, 'w'))
    for k, v in ST.items(): c['steps'][k] = v
    for k, v in JT.items(): c['journeys'][k] = v
    json.dump(c, open(f'{APP}/models/content.json', 'w'), ensure_ascii=False, separators=(',', ':'))
    print('parts added', len(added), 'steps', len(ST), 'journeys', len(JT))


if __name__ == '__main__':
    apply()
